<?php
require_once 'includes/config.php'; require_admin();
$msg=''; $error='';
function fee_money($n){return 'MWK '.number_format((float)$n,2);}
if($_SERVER['REQUEST_METHOD']==='POST') {
 try {
  verify_csrf();
  if(!srms_consume_operation($dbh,'fee.transaction')) throw new RuntimeException('This fee transaction was already submitted.');
  if(isset($_POST['save_due'])) {
   $sid=(int)($_POST['student_id']??0); $year=trim($_POST['academic_year']??''); $term=trim($_POST['term']??''); $due=(float)($_POST['amount_due']??0); $notes=trim($_POST['notes']??'');
   if(!$sid||$year===''||$term===''||$due<0) throw new RuntimeException('Enter a student, academic year, term and a non-negative fee amount.');
   $s=$dbh->prepare('SELECT StudentId,ClassId FROM tblstudents WHERE StudentId=:s');$s->execute([':s'=>$sid]);$st=$s->fetch();if(!$st)throw new RuntimeException('Student not found.');
   $q=$dbh->prepare('INSERT INTO student_term_fees(student_id,class_id,academic_year,term,amount_due,notes,created_by) VALUES(:s,:c,:y,:t,:a,:n,:u) ON DUPLICATE KEY UPDATE class_id=VALUES(class_id),amount_due=VALUES(amount_due),notes=VALUES(notes),updated_at=NOW()');
   $q->execute([':s'=>$sid,':c'=>$st['ClassId'],':y'=>$year,':t'=>$term,':a'=>$due,':n'=>$notes,':u'=>(int)($_SESSION['admin_id']??0)]); audit_log($dbh,'FEE_DUE_SET','Student '.$sid.' / '.$year.' / '.$term.' / '.$due);$msg='Fee obligation saved.';
  } elseif(isset($_POST['record_payment'])) {
   $fid=(int)($_POST['fee_id']??0);$amount=(float)($_POST['amount']??0);$date=$_POST['payment_date']??date('Y-m-d');$method=trim($_POST['payment_method']??'Cash');$receipt=trim($_POST['receipt_number']??'');$notes=trim($_POST['payment_notes']??'');
   if(!$fid||$amount<=0)throw new RuntimeException('Payment amount must be greater than zero.');
   $q=$dbh->prepare('SELECT f.id,f.amount_due,COALESCE(SUM(p.amount),0) paid FROM student_term_fees f LEFT JOIN student_fee_payments p ON p.fee_id=f.id WHERE f.id=:id GROUP BY f.id,f.amount_due');$q->execute([':id'=>$fid]);$fee=$q->fetch();if(!$fee)throw new RuntimeException('Fee record not found.');if($amount>((float)$fee['amount_due']-(float)$fee['paid'])+0.00001)throw new RuntimeException('Payment exceeds the outstanding balance for this fee record.');
   $q=$dbh->prepare('INSERT INTO student_fee_payments(fee_id,amount,payment_date,payment_method,receipt_number,notes,recorded_by) VALUES(:f,:a,:d,:m,:r,:n,:u)');$q->execute([':f'=>$fid,':a'=>$amount,':d'=>$date,':m'=>$method,':r'=>$receipt,':n'=>$notes,':u'=>(int)($_SESSION['admin_id']??0)]);audit_log($dbh,'FEE_PAYMENT','Fee record '.$fid.' payment '.$amount);$msg='Payment recorded successfully.';
  }
 } catch(Throwable $ex){$error=$ex instanceof RuntimeException?$ex->getMessage():'Unable to save fee record. Check the database migration and entered values.';error_log('SRMS fees: '.$ex->getMessage());}
}
$classes=$dbh->query('SELECT id,ClassName,Section FROM tblclasses ORDER BY ClassName,Section')->fetchAll();
$students=$dbh->query('SELECT StudentId,StudentName,RollId,ClassId FROM tblstudents ORDER BY StudentName')->fetchAll();
$class=(int)($_GET['class_id']??0);$year=trim($_GET['academic_year']??'');$term=trim($_GET['term']??'');$status=trim($_GET['status']??'');
$where=[];$params=[];if($class){$where[]='f.class_id=:c';$params[':c']=$class;}if($year!==''){$where[]='f.academic_year=:y';$params[':y']=$year;}if($term!==''){$where[]='f.term=:t';$params[':t']=$term;}
$sql="SELECT f.*,s.StudentName,s.RollId,c.ClassName,c.Section,COALESCE(p.paid,0) paid FROM student_term_fees f JOIN tblstudents s ON s.StudentId=f.student_id JOIN tblclasses c ON c.id=f.class_id LEFT JOIN (SELECT fee_id,SUM(amount) paid FROM student_fee_payments GROUP BY fee_id) p ON p.fee_id=f.id".($where?' WHERE '.implode(' AND ',$where):'')." ORDER BY f.academic_year DESC,f.term,s.StudentName";
$q=$dbh->prepare($sql);$q->execute($params);$rows=$q->fetchAll();$rows=array_values(array_filter($rows,function($r)use($status){$bal=max(0,(float)$r['amount_due']-(float)$r['paid']);$st=$bal<=0?'Full':((float)$r['paid']>0?'Partial':'Unpaid');return $status===''||strtolower($st)===strtolower($status);}));
$totDue=0;$totPaid=0;foreach($rows as $r){$totDue+=(float)$r['amount_due'];$totPaid+=(float)$r['paid'];}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Fees Management | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/font-awesome.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"><style>.fee-stat{padding:16px;border-radius:8px;background:#f5f7fb;margin-bottom:14px}.fee-stat strong{font-size:22px}.form-control{max-width:100%}.table-responsive{overflow-x:auto}@media(max-width:767px){.fee-actions .btn{margin:3px 0;width:100%}}</style></head><body class="top-navbar-fixed"><div class="main-wrapper"><?php include 'includes/topbar.php';?><div class="content-wrapper"><div class="content-container"><?php include 'includes/leftbar.php';?><main class="main-page"><div class="container-fluid"><h2>Fees Management</h2><p class="text-muted">Currency: Malawi Kwacha (MWK)</p><p>Track full payments, partial payments and outstanding balances by class and term.</p><?php if($msg):?><div class="alert alert-success"><?=e($msg)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="row"><div class="col-sm-4"><div class="fee-stat">Total fees due<strong class="center-block"><?=fee_money($totDue)?></strong></div></div><div class="col-sm-4"><div class="fee-stat">Payments received<strong class="center-block"><?=fee_money($totPaid)?></strong></div></div><div class="col-sm-4"><div class="fee-stat">Outstanding balance<strong class="center-block"><?=fee_money(max(0,$totDue-$totPaid))?></strong></div></div></div>
<div class="panel panel-default"><div class="panel-heading"><strong>Set student fees / term</strong></div><div class="panel-body"><form method="post" class="row"><?=csrf_field()?><?=srms_operation_field('fee.transaction')?><input type="hidden" name="save_due" value="1"><div class="col-md-4 form-group"><label>Student</label><select name="student_id" class="form-control" required><option value="">Select student</option><?php foreach($students as $s):?><option value="<?=$s['StudentId']?>"><?=e($s['StudentName'].' — '.$s['RollId'])?></option><?php endforeach;?></select></div><div class="col-md-2 form-group"><label>Academic year</label><input name="academic_year" class="form-control" placeholder="2026/2027" required></div><div class="col-md-2 form-group"><label>Term</label><select name="term" class="form-control" required><option>Term 1</option><option>Term 2</option><option>Term 3</option><option>Final</option></select></div><div class="col-md-2 form-group"><label>Amount due</label><input type="number" min="0" step="0.01" name="amount_due" class="form-control" required></div><div class="col-md-2 form-group"><label>Notes</label><input name="notes" class="form-control" maxlength="255"></div><div class="col-md-12"><button class="btn btn-primary">Save fee obligation</button></div></form></div></div>
<div class="panel panel-default"><div class="panel-heading"><strong>Record payment</strong></div><div class="panel-body"><form method="post" class="row"><?=csrf_field()?><?=srms_operation_field('fee.transaction')?><input type="hidden" name="record_payment" value="1"><div class="col-md-3 form-group"><label>Student fee record</label><select name="fee_id" class="form-control" required><option value="">Select fee record</option><?php foreach($dbh->query("SELECT f.id,f.academic_year,f.term,s.StudentName FROM student_term_fees f JOIN tblstudents s ON s.StudentId=f.student_id ORDER BY f.id DESC") as $f):?><option value="<?=$f['id']?>"><?=e($f['StudentName'].' — '.$f['academic_year'].' '.$f['term'])?></option><?php endforeach;?></select></div><div class="col-md-2 form-group"><label>Amount received</label><input type="number" min="0.01" step="0.01" name="amount" class="form-control" required></div><div class="col-md-2 form-group"><label>Payment date</label><input type="date" name="payment_date" value="<?=date('Y-m-d')?>" class="form-control" required></div><div class="col-md-2 form-group"><label>Method</label><select name="payment_method" class="form-control"><option>Cash</option><option>Bank transfer</option><option>Mobile money</option><option>Cheque</option><option>Other</option></select></div><div class="col-md-3 form-group"><label>Receipt number</label><input name="receipt_number" class="form-control" maxlength="80"></div><div class="col-md-12 form-group"><label>Notes</label><input name="payment_notes" class="form-control" maxlength="255"></div><div class="col-md-12"><button class="btn btn-success">Record payment</button></div></form></div></div>
<div class="panel panel-default"><div class="panel-heading"><strong>Fee balances</strong></div><div class="panel-body"><form method="get" class="row"><div class="col-sm-3 form-group"><label>Class</label><select name="class_id" class="form-control"><option value="0">All classes</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>" <?=$class===(int)$c['id']?'selected':''?>><?=e($c['ClassName'].' '.$c['Section'])?></option><?php endforeach;?></select></div><div class="col-sm-3 form-group"><label>Academic year</label><input name="academic_year" value="<?=e($year)?>" class="form-control" placeholder="2026/2027"></div><div class="col-sm-3 form-group"><label>Term</label><select name="term" class="form-control"><option value="">All terms</option><?php foreach(['Term 1','Term 2','Term 3','Final'] as $t):?><option <?=$term===$t?'selected':''?>><?=e($t)?></option><?php endforeach;?></select></div><div class="col-sm-3 form-group"><label>Payment status</label><select name="status" class="form-control"><option value="">All statuses</option><?php foreach(['Full','Partial','Unpaid'] as $t):?><option value="<?=$t?>" <?=$status===$t?'selected':''?>><?=$t?></option><?php endforeach;?></select></div><div class="col-sm-12 fee-actions"><button class="btn btn-primary">Apply filters</button> <a class="btn btn-default" href="manage-fees.php">Reset</a></div></form><div class="table-responsive"><table class="table table-striped table-bordered"><thead><tr><th>Student</th><th>Roll ID</th><th>Class</th><th>Year / Term</th><th>Due</th><th>Paid</th><th>Balance</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):$bal=max(0,(float)$r['amount_due']-(float)$r['paid']);$st=$bal<=0?'Full':((float)$r['paid']>0?'Partial':'Unpaid');?><tr><td><?=e($r['StudentName'])?></td><td><?=e($r['RollId'])?></td><td><?=e($r['ClassName'].' '.$r['Section'])?></td><td><?=e($r['academic_year'].' / '.$r['term'])?></td><td><?=fee_money($r['amount_due'])?></td><td><?=fee_money($r['paid'])?></td><td><?=fee_money($bal)?></td><td><span class="label label-<?=$st==='Full'?'success':($st==='Partial'?'warning':'danger')?>"><?=$st?></span></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8" class="text-center">No fee records match these filters.</td></tr><?php endif;?></tbody></table></div></div></div></div></main></div></div></div><script src="js/jquery/jquery-2.2.4.min.js"></script><script src="js/bootstrap/bootstrap.min.js"></script></body></html>
